## Why This Is Asked
Streaming data often requires maintaining a running statistic under insertions and deletions. The median is robust and a common interview target for dynamic data structures.

## Key Concepts
- Two-heap approach: keep lower half in a max-heap and upper half in a min-heap.
- Duplicates supported; lazy deletion via a delay map.
- Rebalancing invariant: size difference at most 1; median derived from heap tops.

## Code Example
```javascript
class MedianDS {
  constructor(){
    this.lo = new MaxHeap(); // lower half
    this.hi = new MinHeap(); // upper half
    this.delayed = new Map();
    this.sizeLo = 0;
    this.sizeHi = 0;
  }
  _cleanTop(h) {
    const top = h.peek();
    while (top !== null && this.delayed.get(top) > 0) {
      h.pop();
      this.delayed.set(top, this.delayed.get(top) - 1);
    }
  }
  add(x){
    if (this.sizeLo === 0 || x <= this.lo.peek()) {
      this.lo.push(x); this.sizeLo++;
    } else { this.hi.push(x); this.sizeHi++; }
    this._balance();
  }
  remove(x){
    const loTop = this.lo.peek();
    if (loTop !== null && x <= loTop) {
      this.delayed.set(x, (this.delayed.get(x) || 0) + 1);
      this.sizeLo--;
      if (x === loTop) this._cleanTop(this.lo);
    } else {
      this.delayed.set(x, (this.delayed.get(x) || 0) + 1);
      this.sizeHi--;
      this._cleanTop(this.hi);
    }
    this._balance();
  }
  _balance(){
    if (this.sizeLo > this.sizeHi + 1) {
      this.hi.push(this.lo.pop()); this.sizeLo--; this.sizeHi++;
    } else if (this.sizeHi > this.sizeLo) {
      this.lo.push(this.hi.pop()); this.sizeHi--; this.sizeLo++;
    }
    this._cleanTop(this.lo); this._cleanTop(this.hi);
  }
  getMedian(){
    if (this.sizeLo === 0) return null;
    if (this.sizeLo > this.sizeHi) return this.lo.peek();
    return (this.lo.peek() + this.hi.peek()) / 2;
  }
}
```

## Why This Is Asked
Tests ability to design a dynamic string structure supporting weighted, prefix-based queries and order-statistics. A Trie augmented with per-node aggregates enables efficient prefix sums and k-th retrieval while handling duplicates via cumulative weights.

## Key Concepts
- Trie with per-node aggregates (subtreeWeight, terminalWeight)
- O(len(word)) time complexity for insert/erase operations
- O(len(prefix)) for prefix-sum queries
- O(len(prefix) + len(target_word)) for kth-word queries
- Duplicate handling via cumulative weight values

## Code Example
```javascript
class WeightedTrie {
  constructor() {
    this.root = new TrieNode();
  }

  insertWord(word, w) {
    let node = this.root;
    for (const char of word) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.children[idx]) node.children[idx] = new TrieNode();
      node = node.children[idx];
      node.subtreeWeight += w;
    }
    node.terminalWeight += w;
  }

  eraseWord(word, w) {
    this.insertWord(word, -w);
  }

  queryPrefixSum(prefix) {
    let node = this.traverse(prefix);
    return node ? node.subtreeWeight : 0;
  }

  kthWordWithPrefix(prefix, k) {
    let node = this.traverse(prefix);
    if (!node || node.subtreeWeight < k) return null;
    let word = prefix;
    while (!node.terminalWeight) {
      for (let i = 0; i < 26; i++) {
        if (!node.children[i]) continue;
        if (node.children[i].subtreeWeight >= k) {
          word += String.fromCharCode(97 + i);
          node = node.children[i];
          break;
        }
        k -= node.children[i].subtreeWeight;
      }
    }
    return word;
  }

  traverse(prefix) {
    let node = this.root;
    for (const char of prefix) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.children[idx]) return null;
      node = node.children[idx];
    }
    return node;
  }
}

class TrieNode {
  constructor() {
    this.children = new Array(26).fill(null);
    this.subtreeWeight = 0;
    this.terminalWeight = 0;
  }
}
```

